import React from "react";
import Slider from "../Slider";
import mockData, { columns } from "./mockData";
import DataTable from ".";
import type { Meta, StoryObj } from "@storybook/react";

const meta: Meta<typeof DataTable<{}>> = {
  id: "General/Templates/DataTable",
  title: "General/Templates/Data Table",
  component: DataTable,
  tags: ['skip-test'],
};
export default meta;

type Story = StoryObj<typeof DataTable>;

export const FixedLayout: Story = {
  render: () => {
    const [width, setWidth] = React.useState(720);
    const [height, setHeight] = React.useState(240);
    const data = React.useMemo(() => mockData(50), []);
    return (
      <>
        <div className="w-288 pb-1">
          Width: {width}
          <Slider
            min={400}
            max={800}
            value={[width]}
            onUpdate={(values) => setWidth(values[0])}
            onChange={(values) => setWidth(values[0])}
          />
          Height: {height}
          <Slider
            min={200}
            max={400}
            value={[height]}
            onUpdate={(values) => setHeight(values[0])}
            onChange={(values) => setHeight(values[0])}
          />
        </div>
        <div className="datatable-fixedsize-example" style={{ width }}>
          <DataTable height={height} columns={columns} data={data} defaultRowsPerPage={10} />
        </div>
      </>
    );
  },
};

export const FluidLayout: Story = {
  render: () => {
    const data = React.useMemo(() => mockData(50), []);
    return (
      <div className="gridlayout-example-root">
        <div className="gridlayout-example-side">
          <h2>Side Nav</h2>
        </div>
        <div className="gridlayout-example-top">
          <h2>Header</h2>
        </div>
        <div className="gridlayout-example-datatable">
          <DataTable
            columns={columns}
            data={data}
            defaultRowsPerPage={10}
            paginationProps={{ showRowsPerPage: true }}
          />
        </div>
      </div>
    );
  },
};
FluidLayout.parameters = {
  docs: {
    story: {
      iframeHeight: 400,
      inline: false,
    },
  },
};
